// Fast lookup functions
inline int get_component(int loc) {
    int pos = 0;
    for (int ri = 0; ri < COMP_RLE_COUNT; ri++) {
        pos += COMP_RLE[ri].count;
        if (loc < pos) return COMP_RLE[ri].val;
    }
    return 0;
}

inline bool is_lane_cell(int loc) {
    int pos = 0;
    for (int ri = 0; ri < LANE_RLE_COUNT; ri++) {
        pos += LANE_RLE[ri].count;
        if (loc < pos) return LANE_RLE[ri].val == 1;
    }
    return false;
}

inline bool is_core_cell(int loc) {
    int pos = 0;
    for (int ri = 0; ri < CORE_RLE_COUNT; ri++) {
        pos += CORE_RLE[ri].count;
        if (loc < pos) return CORE_RLE[ri].val == 1;
    }
    return false;
}

inline int manhattan_to_lane(int x, int y) {
    if (x < MD_OX || x >= MD_OX + MD_W) return 99;
    if (y < MD_OY || y >= MD_OY + MD_H) return 99;
    return MD_DATA[(y - MD_OY) * MD_W + (x - MD_OX)];
}

